def mcd(a, b):
    """
    Calcula el máximo común divisor (MCD) de dos enteros no negativos.
    El MCD de un número con 0 es ese número.
    """
    if a == 0:
        return b
    if b == 0:
        return a

    while b:
        a, b = b, a % b
    return a

