def mediana(nums):
    if not nums:
        return None

    nums.sort()
    n = len(nums)

    if n % 2 == 1:
        middle_index = n // 2
        return nums[middle_index]
    else:
        mid1_index = n // 2 - 1
        mid2_index = n // 2
        median = (nums[mid1_index] + nums[mid2_index]) / 2
        return median

