            if i < len(s) - 1 and valor < mapping[s[i+1]]:
                resultado += valor
            else:
                resultado += valor
        return resultado

    def int_a_romanos(n):
        mapping = {1000: 'M', 900: 'CM', 500: 'D', 400: 'CD', 100: 'C', 90: 'XC', 50: 'L', 40: 'XL', 10: 'X', 9: 'IX', 5: 'V', 4: 'IV', 1: 'I'}
        romanos = ""
        for valor, simbolo in sorted(mapping.items(), key=lambda item: item[0], reverse=True):
            while n >= valor:
                romanos += simbolo
                n -= valor
        return romanos

