def obtener(d, camino, defecto=None):
    """
    Busca en un dict anidado siguiendo un camino con puntos ('a.b.c') y devuelve el valor,
    o el defecto si algún tramo no existe.
    """
    partes = camino.split('.')
    resultado = d
    for parte in partes:
        if isinstance(resultado, dict) and parte in resultado:
            resultado = resultado[parte]
        else:
            return defecto
    return resultado

